const root = items[0].json;
const datasets = root.data; // array of 4 Twelve Data API responses

function findByInterval(intervalStr) {
  const found = datasets.find(d => d.meta && d.meta.interval === intervalStr);
  if (!found) throw new Error(`Missing dataset for interval: ${intervalStr}`);
  return found;
}

const raw15m  = findByInterval('15min');
const raw1h = findByInterval('1h');
const raw4h = findByInterval('4h');
const raw1day  = findByInterval('1day');

function normalize(values) {
  return values.map(v => ({
    time: new Date(v.datetime),
    open: parseFloat(v.open),
    high: parseFloat(v.high),
    low: parseFloat(v.low),
    close: parseFloat(v.close),
    volume: v.volume !== undefined ? parseFloat(v.volume) : null,
  })).sort((a, b) => a.time - b.time);
}

function round(n, d = 5) {
  if (n === null || n === undefined || isNaN(n)) return null;
  const f = Math.pow(10, d);
  return Math.round(n * f) / f;
}

function ema(values, period) {
  const k = 2 / (period + 1);
  const out = [values[0]];
  for (let i = 1; i < values.length; i++) {
    out.push(values[i] * k + out[i - 1] * (1 - k));
  }
  return out;
}

function rsi(candles, period = 14) {
  if (candles.length < period + 1) return null;
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const diff = candles[i].close - candles[i - 1].close;
    diff >= 0 ? gains += diff : losses -= diff;
  }
  let avgGain = gains / period;
  let avgLoss = losses / period;
  for (let i = period + 1; i < candles.length; i++) {
    const diff = candles[i].close - candles[i - 1].close;
    const gain = diff > 0 ? diff : 0;
    const loss = diff < 0 ? -diff : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
  }
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return round(100 - 100 / (1 + rs), 2);
}

function macd(candles, fast = 12, slow = 26, signal = 9) {
  const closes = candles.map(c => c.close);
  if (closes.length < slow + signal) return null;
  const emaFast = ema(closes, fast);
  const emaSlow = ema(closes, slow);
  const macdLine = emaFast.map((v, i) => v - emaSlow[i]);
  const signalLine = ema(macdLine, signal);
  const histogram = macdLine.map((v, i) => v - signalLine[i]);
  const last = macdLine.length - 1;
  return {
    macd: round(macdLine[last]),
    signal: round(signalLine[last]),
    histogram: round(histogram[last]),
  };
}

function atr(candles, period = 14) {
  if (candles.length < period + 1) return null;
  const trs = [];
  for (let i = 1; i < candles.length; i++) {
    const c = candles[i], p = candles[i - 1];
    trs.push(Math.max(c.high - c.low, Math.abs(c.high - p.close), Math.abs(c.low - p.close)));
  }
  const recent = trs.slice(-period);
  return round(recent.reduce((a, b) => a + b, 0) / recent.length);
}

function vwap(candles) {
  const hasVolume = candles.every(c => c.volume && c.volume > 0);
  if (!hasVolume) return null; // common for forex pairs — flagged, not faked
  let cumPV = 0, cumVol = 0;
  candles.forEach(c => {
    const tp = (c.high + c.low + c.close) / 3;
    cumPV += tp * c.volume;
    cumVol += c.volume;
  });
  return round(cumPV / cumVol);
}

function trendLabel(ema20, ema50) {
  if (ema20 == null || ema50 == null) return "unknown";
  const diffPct = ((ema20 - ema50) / ema50) * 100;
  if (diffPct > 0.05) return "up";
  if (diffPct < -0.05) return "down";
  return "sideways";
}

function summarize(candles, label) {
  if (!candles || candles.length < 30) {
    return { timeframe: label, error: "insufficient data" };
  }
  const closes = candles.map(c => c.close);
  const last = candles[candles.length - 1];
  const emaFastArr = ema(closes, 20);
  const emaSlowArr = closes.length >= 50 ? ema(closes, 50) : null;
  const lastEma20 = emaFastArr[emaFastArr.length - 1];
  const lastEma50 = emaSlowArr ? emaSlowArr[emaSlowArr.length - 1] : null;

  return {
    timeframe: label,
    lastClose: round(last.close),
    lastTime: last.time,
    rsi14: rsi(candles, 14),
    macd: macd(candles),
    ema20: round(lastEma20),
    ema50: round(lastEma50),
    atr14: atr(candles, 14),
    vwap: vwap(candles),
    trend: trendLabel(lastEma20, lastEma50),
    volumeAvailable: candles.every(c => c.volume && c.volume > 0),
  };
}

const candles15m  = normalize(raw15m.values);
const candles1h = normalize(raw1h.values);
const candles4h = normalize(raw4h.values);
const candles1day  = normalize(raw1day.values);

const rawTicker = raw15m.meta.symbol;
const epicCode = rawTicker.replace('/', '');

return [{
  json: {
    ticker: rawTicker,
    epicCode: epicCode,
    indicators: {
      "15m":  summarize(candles15m, "15m"),
      "1h": summarize(candles1h, "1h"),
      "4h": summarize(candles4h, "4h"),
      "1day":  summarize(candles1day, "1day"),
    },
    recentCandles: {
      "15m": candles15m.slice(-10),
      "1h": candles1h.slice(-10),
      "4h": candles4h.slice(-10),
      "1day": candles1day.slice(-10),
    }
  }
}];

const rawSymbol = $input.first().json.ticker;

// Map common tickers to news-friendly search terms
const symbolMap = {
  "BTC/USD": "Bitcoin",
  "ETH/USD": "Ethereum",
  "XRP/USD": "Ripple XRP",
  "EUR/USD": "EUR USD forex",
  "GBP/USD": "GBP USD forex",
  "USD/JPY": "USD JPY forex",
  "AUD/USD": "AUD USD forex",
  "XAU/USD": "Gold XAU forex",
  "GBP/JPY": "GBP JPY forex"
};

const searchTerm = symbolMap[rawSymbol] || rawSymbol;

return [{ json: { ticker: rawSymbol, searchTerm: searchTerm } }];

const raw = $input.first().json.content[0].text;

// Strip markdown code fences if present
const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    shortTermSentiment: {
      category: "Neutral",
      score: 0,
      rationale: "Failed to parse sentiment response: " + e.message
    }
  };
}

return [{
  json: {
    sentiment: parsed.shortTermSentiment || parsed
  }
}];

const output = items[0].json.output;

function extractNumber(text, label) {
  const regex = new RegExp(label + "\\s*:?\\s*([0-9]+\\.?[0-9]*)", "i");
  const match = text.match(regex);
  return match ? parseFloat(match[1]) : null;
}

const action = /BUY/i.test(output) ? "BUY" : /SELL/i.test(output) ? "SELL" : "HOLD";
const entry = extractNumber(output, "Entry Price");
const stopLoss = extractNumber(output, "Stop-Loss");
const target = extractNumber(output, "Target Price");

let rrRatio = null;
let warning = null;

const MINIMUM_RR = 2;

if (entry && stopLoss && target && action !== "HOLD") {
  const risk = Math.abs(entry - stopLoss);
  const reward = Math.abs(target - entry);
  rrRatio = (reward / risk).toFixed(2);

  if (parseFloat(rrRatio) < MINIMUM_RR) {
    warning = `⚠️ R:R is only 1:${rrRatio} — below the ${MINIMUM_RR} minimum. Weak setup, consider skipping.`;
  }
}

const now = new Date();
const utcHour = now.getUTCHours();
let session = "Off-peak";
if (utcHour >= 13 && utcHour < 17) session = "London/NY Overlap (high liquidity)";
else if (utcHour >= 8 && utcHour < 13) session = "London session";
else if (utcHour >= 0 && utcHour < 9) session = "Tokyo session";
else if (utcHour >= 22 || utcHour < 1) session = "Dead zone (low liquidity - use caution)";

return [{
  json: {
    ...items[0].json,
    action,
    entry,
    stopLoss,
    target,
    rrRatio,
    session,
    warning
  }
}];

const epic = $('Aggregate1').first().json.data[0].epicCode;
const ai = $('Code in JavaScript1').first().json;

const MARGIN_PCT_OF_FUNDS = 0.5; // 50% of available funds
const CAPITAL_EPIC = { XAUUSD: 'GOLD' };

// Real leverage your demo account uses (check the "Leverage" column in your portfolio)
const LEVERAGE = {
  EURUSD: 100,
  GBPUSD: 100,
  GBPJPY: 100,
  XAUUSD: 100,
  BTCUSD: 20,
};

// ---- Available funds ----
const accounts = $('Get Balance').first().json.accounts || [];
const acct = accounts.find(a => a.preferred) || accounts[0];
const bal = acct?.balance || {};

let available = Number(bal.available);
if (!(available > 0)) available = Number(bal.balance);
if (!(available > 0)) available = Number(bal.deposit);
if (!(available > 0)) throw new Error('No funds found: ' + JSON.stringify(bal));

// ---- Market rules (min size, step, max size) ----
const m = $('Get Market Rules').first().json;
const minSize = Number(m.dealingRules?.minDealSize?.value);
const maxSize = Number(m.dealingRules?.maxDealSize?.value) || Infinity;
const step = Number(m.dealingRules?.minSizeIncrement?.value) || minSize;
const price = Number(m.snapshot?.offer) || Number(ai.entry);

// ---- Leverage: use our table, fall back to the API rate ----
let leverage = LEVERAGE[epic];
let leverageSource = 'table';
if (!leverage) {
  const mf = Number(m.instrument?.marginFactor);
  leverage = mf ? 100 / mf : NaN;
  leverageSource = 'api';
}

if (!minSize || !leverage || !price) {
  throw new Error(`Missing market rules for ${epic}: ` + JSON.stringify({ minSize, leverage, price }));
}

const quoteUsd = epic.endsWith('JPY') ? 1 / 150 : 1;
const marginPerUnitUsd = (price * quoteUsd) / leverage;

// ---- Size ----
let size = (available * MARGIN_PCT_OF_FUNDS) / marginPerUnitUsd;
const decimals = (String(step).split('.')[1] || '').length;
size = Math.floor(size / step + 1e-9) * step;
size = Number(size.toFixed(decimals));

let usedMinimum = false;
if (size < minSize) { size = minSize; usedMinimum = true; }
size = Math.min(size, maxSize);

const marginNeeded = size * marginPerUnitUsd;
if (marginNeeded > available) {
  throw new Error(`Not enough free funds for minimum ${epic}: need ~$${marginNeeded.toFixed(2)}, have $${available}`);
}

// ---- Build the order ----
const direction = String(ai.action || '').toUpperCase();
const stopLevel = Number(ai.stopLoss);
const profitLevel = Number(ai.target);

if (!['BUY', 'SELL'].includes(direction)) {
  throw new Error(`Bad direction for ${epic}: ${JSON.stringify(ai)}`);
}
if (!(stopLevel > 0) || !(profitLevel > 0)) {
  throw new Error(`Bad stop/target for ${epic}: ${JSON.stringify(ai)}`);
}

const order = {
  epic: CAPITAL_EPIC[epic] || epic,
  direction,
  size,
  guaranteedStop: false,
  stopLevel,
  profitLevel,
};

return [{ json: {
  size, usedMinimum, leverage, leverageSource,
  marginUsd: Number(marginNeeded.toFixed(2)),
  available, order
} }];

const pairs = [
  { ticker: "EUR/USD", epicCode: "EURUSD" },
  { ticker: "GBP/USD", epicCode: "GBPUSD" },
  { ticker: "XAU/USD", epicCode: "XAUUSD" },
{ ticker: "BTC/USD", epicCode: "BTCUSD" },
{ ticker: "GBP/JPY", epicCode: "GBPJPY" },
];

return pairs.map(pair => ({ json: pair }));
